// UTXOSelectionFilters defines model for UtxoSelectionFilters.
//
// Narrow the UTXO candidate pool. All specified filters are AND-ed together. This feature is currently in beta and might be subject to changes.
type UTXOSelectionFilters struct {
	// Only include UTXOs that have ALL of these labels.
	IncludeAllLabels []string `json:"includeAllLabels,omitempty"`
	// Only include UTXOs that have at least one of these labels.
	IncludeAnyLabels []string `json:"includeAnyLabels,omitempty"`
	// Exclude UTXOs that have any of these labels.
	ExcludeAnyLabels []string `json:"excludeAnyLabels,omitempty"`
	// Only include UTXOs from this specific address.
	Address *string `json:"address,omitempty"`
	// Minimum UTXO amount in the asset's base unit (e.g., BTC).
	MinAmount *string `json:"minAmount,omitempty"`
	// Maximum UTXO amount in the asset's base unit (e.g., BTC).
	MaxAmount *string `json:"maxAmount,omitempty"`
}

